import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as t}from"./chunks/DIS.DdpTdGGD.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as n,o as p,c as r,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Inter-apps","description":"","frontmatter":{},"headers":[],"relativePath":"use/interapp.md","filePath":"use/interapp.md"}'),l={name:"use/interapp.md"};function d(h,s,u,m,b,g){return p(),r("div",null,[...s[0]||(s[0]=[c('<div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Inter-app settings</p></div><br><p>Inter-app settings offers two ways to interface xDrip with other apps: local broadcast (internal to this phone) and web service (internal and external).</p><h3 id="local-broadcast" tabindex="-1">Local Broadcast <a class="header-anchor" href="#local-broadcast" aria-label="Permalink to &quot;Local Broadcast&quot;">​</a></h3><p>Broadcast locally will make xDrip send internal messages that can be used by other apps like Nightwatch or AAPS.</p><div class="admonition xdripitem"><p class="admonition-title">Broadcast locally <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Enable local broadcast of data so other apps (e.g. NightWatch) can listen on new values</p></div><p>If you&#39;re using calibration plugins or filtering, you can select to broadcast raw data or filtered/calibrated data.</p><div class="admonition xdripitem"><p class="admonition-title">Send Display Glucose <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Use noise smoothing and plugins etc. (if enabled) for broadcasted value</p></div><p>You can also block noisy data broadcast for safety. By default, only extreme noise level is not broadcasted.</p><div class="admonition xdripitem"><p class="admonition-title">Noise Blocking</p><p> Level at which noisy data should not be broadcast as it could confuse receiving apps</p></div><p>Recent apps/phones should accept compatible broadcast. Do not uncheck.</p><div class="admonition xdripitem"><p class="admonition-title">Compatible Broadcast <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Send broadcasts without locking to the older permission model</p></div><p>You can specify the identified receiver if you want xDrip to send messages only to a specific app. One of the most common uses is when xDrip is <a href="https://androidaps.readthedocs.io/en/latest/Configuration/xdrip.html#identify-receiver" target="_blank" rel="noreferrer">AAPS</a> data source.</p><div class="admonition xdripitem"><p class="admonition-title">Identify receiver</p><p> Only send to named package</p></div><h5 id="receiving-from-nsclient" tabindex="-1">Receiving from NSClient. <a class="header-anchor" href="#receiving-from-nsclient" aria-label="Permalink to &quot;Receiving from NSClient.&quot;">​</a></h5><p>xDrip can also receive messages using this feature: you can enable or disable receiving data and treatments from other broadcasting apps.</p><div class="admonition xdripitem"><p class="admonition-title">Accept Glucose <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Process glucose data received from NSClient app</p></div><div class="admonition xdripitem"><p class="admonition-title">Accept Treatments <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Process treatment data received from NSClient app</p></div><p>You can enable or disable (<strong>disable for AAPS!!!</strong>) the sound that plays after updating xDrip profile.</p><div class="admonition xdripitem"><p class="admonition-title">Import Sounds <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Play sounds when importing significant data such as profiles</p></div><p>Be careful when accepting calibrations from other apps.</p><div class="admonition xdripitem"><p class="admonition-title">Accept Calibrations <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Process calibrations received from other apps</p></div><h3 id="web-service" tabindex="-1">Web Service <a class="header-anchor" href="#web-service" aria-label="Permalink to &quot;Web Service&quot;">​</a></h3><p>Original documentation <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/technical/Local_Web_Services.md" target="_blank" rel="noreferrer">here</a>.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>If you have another app using port 17580 (like Diabox) you should disable this feature.<br> Note the service is not available as secured http and recent <a href="./../smartwatch/smartwatch.html#fitbit">Fitbit</a> apps might not accept data from it.</p></div><p>Web service will open a local web service on your device to allow other devices (smartwatches) and apps to receive data from it.<br> The web server will respond to requests on address <code>127.0.0.1</code> port <code>17580</code></p><div class="admonition xdripitem"><p class="admonition-title">xDrip Web Service <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Operate a local web server for interacting with Fitbit Ionic etc</p></div><p>By default the web service is only available to your device; you can open it so that other devices on the network can access it. Make sure you need the feature enabled and understand the security implications. Make sure a Shared Secret is set.</p><div class="admonition xdripitem"><p class="admonition-title">Open Web Service <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Accept connections from any network instead of just internally within this device. There are security implications to enabling this! Shared Secret will be required if set.</p></div><div class="admonition xdripitem"><p class="admonition-title">Web service secret</p><p> Shared Secret for open web service (should match your Nightscout API secret)</p></div><h4 id="open-option" tabindex="-1">Open option <a class="header-anchor" href="#open-option" aria-label="Permalink to &quot;Open option&quot;">​</a></h4><p>The service has an <code>Open Web Service</code> option. If this is enabled then connections can be made through any network interface instead of being restricted to the loopback on-device network only. Typically enabling this option exposes the wifi / lan / bluetooth pan connection of the device although it is possible that it could be exposed via cellular as well if the carrier supports public ip addressing.</p><p>Be very careful enabling this option as there are powerful features accessible, for example the tasker interface. It is best used in conjunction with the Authentication option described below.</p><h4 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h4><p>For safety reasons (anybody on the network can access this service) you should protect it with a password; if you have a Nightscout site use your API_SECRET.</p><p>If the <code>xDrip Web Service Secret</code> is set to anything other than an empty string (the default) then requests coming in via the open non-loopback networks will have to supply a http header <code>api-secret</code> which contains the SHA1 hash of the same secret password or their connection will be rejected. Rejection information is stored in the Event Log and returned via the http response. The result code 403 (forbidden) is set when a connection is rejected.</p><p>Additionally, if a client supplies the <code>api-secret</code> header, then even if the xDrip secret is not set then the request will be rejected. This feature is so that client devices can be assured they are connecting to the correct xDrip instance (by using different secrets). This could be significant when looping for example.</p><p>Authentication is not required on the loopback local network interface (127.0.0.1)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api-secret: 915858afa2278f25527f192038108346164b47f2</span></span></code></pre></div><p>Above shows http header for password <code>Abc</code></p><h4 id="nightscout-pebble-endpoint" tabindex="-1">Nightscout Pebble endpoint <a class="header-anchor" href="#nightscout-pebble-endpoint" aria-label="Permalink to &quot;Nightscout Pebble endpoint&quot;">​</a></h4><p><code>/pebble</code> emulates the same URL on Nightscout, with a watchface which supports this, you can enter the address on the watchface, for example, set the data endpoint on Pebble Nightscout watchface to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/pebble</span></span></code></pre></div><h4 id="sgvjson-endpoint" tabindex="-1">sgv.json endpoint <a class="header-anchor" href="#sgvjson-endpoint" aria-label="Permalink to &quot;sgv.json endpoint&quot;">​</a></h4><p><code>/sgv.json</code> emulates <code>/api/v1/entries/sgv.json?count=24</code> on Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json</span></span></code></pre></div><p>The first record will contain a hint as to the units being used, <code>units_hint</code> will be <code>mgdl</code> or <code>mmol</code> to indicate the user&#39;s preference but the values will always be sent as mgdl</p><p>You can also access the steps endpoint by appending a query parameter</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?steps=1234</span></span></code></pre></div><p>When doing this look for <code>steps_result</code> number in the first record of the json reply, 200 indicates success, anything else failure to set the steps value. Steps value should be the current cumulative step counter from the device.</p><p>You can also access the heart endpoint by appending a query parameter</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?heart=123</span></span></code></pre></div><p>When doing this look for <code>heart_result</code> number in the first record of the json reply, 200 indicates success, anything else failure to set the heart bpm value. Heart value should be the current bpm now from the device.</p><p>You can combine both like a normal query string:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?steps=1234&amp;heart=123</span></span></code></pre></div><p>There is another option <code>brief_mode=Y</code> which you can use to exclude some of the data fields from the results to reduce response size.</p><p>There is another option <code>no_empty=Y</code> which you can use so that an empty data set returns <code>&quot;&quot;</code> instead of <code>&quot;[]&quot;</code></p><p>There is another option <code>all_data=Y</code> which you can use to get data additionally from the previous sensor session.</p><p>There is another option <code>sensor=Y</code> which you can use to get data about sensor age</p><p>There is another option <code>collector=Y</code> which you can use to get alert messages from the collector. Nothing will be returned if the message is empty.</p><p>You can also access the tasker endpoint by appending a query parameter</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?tasker=osnooze</span></span></code></pre></div><p>look for <code>tasker_result</code> in the first line of the json reply to indicate success or failure.</p><p><code>OSNOOZE</code> is opportunistic snooze which you can call even when there is no alert playing</p><p><code>SNOOZE</code> is the traditional tasker snooze which will send snooze to followers and uses more cpu</p><h4 id="treatmentsjson-endpoint" tabindex="-1">treatments.json endpoint <a class="header-anchor" href="#treatmentsjson-endpoint" aria-label="Permalink to &quot;treatments.json endpoint&quot;">​</a></h4><p><code>/treatments.json</code> emulates <code>/api/v1/treatments.json?count=24</code> on Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/treatments.json</span></span></code></pre></div><h4 id="statusjson-endpoint" tabindex="-1">status.json endpoint <a class="header-anchor" href="#statusjson-endpoint" aria-label="Permalink to &quot;status.json endpoint&quot;">​</a></h4><p>This implements a small subset of the data you might receive from Nightscout&#39;s status.json</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/status.json</span></span></code></pre></div><p>Results look like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;thresholds&quot;:{&quot;bgHigh&quot;:9.4,&quot;bgLow&quot;:3.9}}</span></span></code></pre></div><p>High and low marks set within the app represented in the local units.</p><h4 id="libre-2-endpoint" tabindex="-1">Libre 2 endpoint <a class="header-anchor" href="#libre-2-endpoint" aria-label="Permalink to &quot;Libre 2 endpoint&quot;">​</a></h4><p><code>/Libre2ConnectCode.json</code> returns Bluetooth unlock buffer and device Mac address.</p><p>This is used by <a href="./sync.html#whole-house">whole house</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/Libre2ConnectCode.json</span></span></code></pre></div><h4 id="tasker-endpoint" tabindex="-1">Tasker endpoint <a class="header-anchor" href="#tasker-endpoint" aria-label="Permalink to &quot;Tasker endpoint&quot;">​</a></h4><p>The <code>/tasker</code> endpoint lets you push requests to the tasker interface via http. So a watch face which can only support web based endpoints (eg FitBit) could send a snooze request as below:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/tasker/SNOOZE</span></span></code></pre></div><h4 id="steps-endpoint" tabindex="-1">Steps endpoint <a class="header-anchor" href="#steps-endpoint" aria-label="Permalink to &quot;Steps endpoint&quot;">​</a></h4><p><code>/steps</code> allows for setting the current step counter data</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/steps/set/1234</span></span></code></pre></div><p>This should be the current cumulative step counter on the device measuring steps. Not a historical record.</p><h4 id="heart-endpoint" tabindex="-1">Heart endpoint <a class="header-anchor" href="#heart-endpoint" aria-label="Permalink to &quot;Heart endpoint&quot;">​</a></h4><p><code>/heart</code> allows for setting the current heart rate bpm data</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/heart/set/123/1</span></span></code></pre></div><p>This should be the current heart rate in BPM on the measuring device. Not a historical record. The first parameter is BPM and the second is accuracy. If unsure of accuracy parameter just set to 1.</p><br><h3 id="broadcast-service-api" tabindex="-1">Broadcast Service API <a class="header-anchor" href="#broadcast-service-api" aria-label="Permalink to &quot;Broadcast Service API&quot;">​</a></h3><p>This service allows broadcast of xDrip values as an API and can be used by external apps like <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration" target="_blank" rel="noreferrer">WatchDrip+</a> (enable the feature for WatchDrip+).</p><div class="admonition xdripitem"><p class="admonition-title">Broadcast Service API <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Enables xDrip communication with third-party applications by using new API</p></div><div class="admonition xdripitem"><p class="admonition-title">Enable IoB reporting in API <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Enable IoB value reporting in Web Service API endpoint used by some smartwatches</p></div><div class="admonition xdripitem"><p class="admonition-title">Fetch IoB from Companion App <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Fetch IoB value from companion app running on the same device, such as the Omnipod 5 App</p></div><br><h3 id="google-health-connect" tabindex="-1">Google Health connect <a class="header-anchor" href="#google-health-connect" aria-label="Permalink to &quot;Google Health connect&quot;">​</a></h3><p>You can share information with Google Health.</p><div class="admonition xdripitem"><p class="admonition-title">Google Health Connect</p><p> Send and receive data from Google Health Connect and Google Fit</p></div><p>You need <a href="https://play.google.com/store/apps/details?id=com.google.android.apps.healthdata&amp;hl=en&amp;gl=US" target="_blank" rel="noreferrer">Health Connect</a> installed on your device, which is available for Android 8 and above.</p><div class="admonition xdripitem"><p class="admonition-title">Use Health Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Requires Android 8+ and Google companion application or Android 14+</p></div><p>You can then decide to use incoming and allow outgoing data.</p><p>xDrip can share steps, heart rate and BG with Google Health.</p><div class="admonition xdripitem"><p class="admonition-title">Get data from Health Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Send data to Health Connect <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Manage permissions</p><p> Open Health Connect Settings to manually manage permissions</p></div><p>On some Android versions (notably 15 and 16) xDrip isn&#39;t allowed to open its Health Connect permission screen directly. It then opens the Health Connect app instead: go to <em>App permissions</em> and select xDrip to manage them. If Health Connect can&#39;t be opened at all, a message asks you to open the Health Connect app yourself and manage xDrip&#39;s permissions there.</p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',108)])])}const C=n(l,[["render",d]]);export{_ as __pageData,C as default};
